using System;
using System.Collections.Generic;

// PROGRAM: Simulasi Algoritma Round-Robin Load Balancer Sederhana
public class RoundRobinLoadBalancer
{
    private readonly List<string> _nodes;
    private int _currentIndex = 0;
    private readonly object _lock = new();

    public RoundRobinLoadBalancer(IEnumerable<string> nodes)
    {
        _nodes = new List<string>(nodes);
        if (_nodes.Count == 0) throw new ArgumentException("Daftar node tidak boleh kosong.");
    }

    public string GetNextNode()
    {
        lock (_lock)
        {
            string node = _nodes[_currentIndex];
            _currentIndex = (_currentIndex + 1) % _nodes.Count; // Berputar kembali ke 0 saat mencapai ujung
            return node;
        }
    }
}

public class Program
{
    public static void Main()
    {
        var cluster = new[] { "node-api-01:5000", "node-api-02:5000", "node-api-03:5000" };
        var lb = new RoundRobinLoadBalancer(cluster);

        Console.WriteLine("=== SIMULASI DISTRIBUSI REQUEST LOAD BALANCER ===");
        for (int i = 1; i <= 6; i++)
        {
            Console.WriteLine($"Request #{i} diarahkan ke: {lb.GetNextNode()}");
        }
    }
}

