using System;

public class ApiGatewayRouter
{
    public static string RouteRequest(string? path)
    {
        if (string.IsNullOrWhiteSpace(path)) return "fallback-service:5000";

        string clean = path.Trim();
        if (clean.StartsWith("/api/v1/auth", StringComparison.OrdinalIgnoreCase))
            return "auth-service:5001";

        if (clean.StartsWith("/api/v1/orders", StringComparison.OrdinalIgnoreCase))
            return "order-service:5002";

        if (clean.StartsWith("/api/v1/payments", StringComparison.OrdinalIgnoreCase))
            return "payment-service:5003";

        return "fallback-service:5000";
    }

    public static void Main()
    {
        Console.WriteLine(RouteRequest("/api/v1/orders/123"));
        Console.WriteLine(RouteRequest("/api/v1/unknown"));
    }
}
